private class Cached<T : Any>(private val build: () -> T) {
    private var value: T? = null
    operator fun getValue(thisRef: Any?, property: KProperty<*>): T = value ?: build().also { value = it }
}

private val Ink = SolidColor(Color.Black)

private fun symbol(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = autoMirror)
        .addGroup(translationY = 960f)
        .fill(path)
        .build()

private fun ImageVector.Builder.fill(path: String) = addPath(addPathNodes(path), fill = Ink)

private fun ImageVector.Builder.stroke(
    path: String,
    width: Float,
    cap: StrokeCap = StrokeCap.Round,
    join: StrokeJoin = StrokeJoin.Round,
) = addPath(addPathNodes(path), stroke = Ink, strokeLineWidth = width, strokeLineCap = cap, strokeLineJoin = join)
